  if key:sub(-3) == "ies" then return { key, key:sub(1, -4) .. "y", key:sub(1, -2) } end
  if key:sub(-1) == "s" then return { key, key:sub(1, -2) } end
  if key:sub(-1) == "y" then return { key, key:sub(1, -2) .. "ies", key:sub(1, -2) .. "ie" } end
  return { key, key .. "s" }
end

