---@type table<string, table> The wait of the last onResourceStart, by resource name
local pendingStart = {}

-- onResourceStart comes before the resource is "started": the listeners wait for it, so that their calls to its
-- exports are not refused. A stop, a newer start or 10 s without reaching "started" drop the wait.
AddEventHandler("onResourceStart", function(name)
