  local token = {}
  pendingStart[name] = token
  CreateThread(function()
    local deadline = GetGameTimer() + 10000
    while pendingStart[name] == token and GetResourceState(name) ~= "started" and GetGameTimer() < deadline do Wait(0) end
    if pendingStart[name] ~= token then return end
    pendingStart[name] = nil
    if GetResourceState(name) == "started" then dispatch(name, "startHandlers", "onStart") end
  end)
end)
AddEventHandler("onResourceStop", function(name)
  pendingStart[name] = nil
  dispatch(name, "stopHandlers", "onStop")
end)

